import { Innertube } from 'youtubei.js';
import { parseTimedText } from './parseTimedText.js';
import { TranscriptUnavailableError, type Transcript, type TranscriptProvider } from './types.js';

interface CaptionTrack {
  language_code: string;
  kind?: string;
  base_url: string;
}

// Prefer human-written English captions, then auto-generated English, then whatever exists.
function pickTrack(tracks: CaptionTrack[]): CaptionTrack | undefined {
  return (
    tracks.find((track) => track.language_code.startsWith('en') && track.kind !== 'asr') ??
    tracks.find((track) => track.language_code.startsWith('en')) ??
    tracks[0]
  );
}

/**
 * Reads captions straight from YouTube's caption tracks.
 *
 * LangChain's YoutubeLoader calls youtubei.js getTranscript(), which YouTube currently
 * rejects (HTTP 400), and it also discards timestamps. Downloading the caption track
 * directly works and keeps the timing we need for citations and time-window chunking.
 */
export class YoutubeTranscriptProvider implements TranscriptProvider {
  async getTranscript(youtubeId: string): Promise<Transcript> {
    try {
      const youtube = await Innertube.create({ retrieve_player: false });
      // The ANDROID client is the one that returns caption tracks reliably.
      const info = await youtube.getInfo(youtubeId, { client: 'ANDROID' });

      const track = pickTrack(info.captions?.caption_tracks ?? []);
      if (!track) {
        throw new TranscriptUnavailableError('This video has no captions.');
      }

      const response = await fetch(track.base_url);
      if (!response.ok) {
        throw new TranscriptUnavailableError(`Caption download failed (HTTP ${response.status}).`);
      }

      const segments = parseTimedText(await response.text());
      if (segments.length === 0) {
        throw new TranscriptUnavailableError('The caption track was empty.');
      }

      return {
        youtubeId,
        language: track.language_code,
        isAutoGenerated: track.kind === 'asr',
        segments,
      };
    } catch (error) {
      if (error instanceof TranscriptUnavailableError) throw error;
      throw new TranscriptUnavailableError(
        `Could not load transcript: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  }
}
